const headers = $input.first().json.headers || {};
const token   = headers['x-internal-token'] || headers['X-Internal-Token'];

if (!token || token !== $env.INTERNAL_WEBHOOK_SECRET) {
  throw new Error('UNAUTHORIZED_REQUEST: invalid or missing token');
}

const body = $input.first().json.body || $input.first().json;
return [{ json: body }];

// ── Prepare unified context for CRM routing ─────────────────────────────
// Merges trigger payload + DB lead record + client config.
// Determines CRM provider and maps AZOX status to CRM stage.

const trigger = $items('Set Idempotency Key')[0].json;
const lead    = $input.first().json;

if (!lead || !lead.lead_id) {
  throw new Error(`LEAD_NOT_FOUND: ${trigger.lead_id}`);
}

const parseCol = (v) => {
  if (!v) return {};
  if (typeof v === 'object') return v;
  try { return JSON.parse(v); } catch(e) { return {}; }
};

const clientConfig = parseCol(lead.client_config);
const crmConfig    = clientConfig.crm || {};

// Determine which CRM to use (client config → env fallback)
const crmProvider = (crmConfig.provider || $env.DEFAULT_CRM_PROVIDER || 'hubspot').toLowerCase();

// AZOX status → HubSpot deal stage internal value
// Client can override via crm_config.stage_map
const defaultStageMap = {
  new:              'appointmentscheduled',
  scored:           'qualifiedtobuy',
  in_sequence:      'presentationscheduled',
  replied:          'decisionmakerboughtin',
  meeting_proposed: 'contractsent',
  meeting_booked:   'closedwon'
};
const stageMap  = { ...defaultStageMap, ...(crmConfig.stage_map || {}) };
const dealStage = stageMap[lead.status] || stageMap['scored'];

// HubSpot pipeline ID — default or client-specific
const pipelineId = crmConfig.hubspot_pipeline_id || $env.HUBSPOT_PIPELINE_ID || 'default';

// Build the flat contact properties for HubSpot upsert
const hubspotContactProps = {
  email:            lead.email,
  firstname:        lead.first_name || '',
  lastname:         lead.last_name  || '',
  jobtitle:         lead.title      || '',
  company:          lead.company    || '',
  phone:            lead.phone      || '',
  website:          lead.website    || '',
  hs_lead_status:   lead.status,
  // Custom AZOX properties
  azox_lead_id:     lead.lead_id,
  azox_score:       String(lead.score || 0),
  azox_tier:        lead.tier        || '',
  azox_status:      lead.status      || '',
  azox_last_action: trigger.event    || '',
  azox_meeting_booked: trigger.event === 'meeting.booked' ? 'true' : undefined
};

// Remove undefined values
Object.keys(hubspotContactProps).forEach(k => {
  if (hubspotContactProps[k] === undefined) delete hubspotContactProps[k];
});

// Deal properties
const hubspotDealProps = {
  dealname:    `${lead.company || ''} — ${lead.full_name || lead.email}`,
  amount:      String(lead.annual_revenue || ''),
  dealstage:   dealStage,
  pipeline:    pipelineId,
  closedate:   new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10),
  azox_lead_id: lead.lead_id
};

return [{
  json: {
    ...lead,
    ...trigger,
    lead_id:                lead.lead_id,
    crm_provider:           crmProvider,
    deal_stage:             dealStage,
    pipeline_id:            pipelineId,
    hubspot_contact_id:     lead.hubspot_contact_id     || null,
    hubspot_deal_id:        lead.hubspot_deal_id         || null,
    salesforce_contact_id:  lead.salesforce_contact_id  || null,
    salesforce_opp_id:      lead.salesforce_opportunity_id || null,
    hubspot_contact_props:  hubspotContactProps,
    hubspot_deal_props:     hubspotDealProps,
    client_config:          clientConfig,
    crm_config:             crmConfig,
    prepared_at:            new Date().toISOString()
  }
}];

// ── HubSpot 429-aware HTTP wrapper ───────────────────────────────────────
// Retries on 429 Too Many Requests (HubSpot: 100 req / 10 sec).
// Respects Retry-After header if present; falls back to 2s → 4s → 8s.
// Max 3 retries. Throws on 4th failure or non-429 error.
const hsRequest = async (opts, attempt = 0) => {
  try {
    return await $helpers.httpRequest(opts);
  } catch (err) {
    const status = err.response?.statusCode || err.statusCode || 0;
    if (status === 429 && attempt < 3) {
      const retryAfterMs =
        parseInt(err.response?.headers?.['retry-after'] || '0', 10) * 1000
        || (2 ** attempt) * 2000;   // 2s, 4s, 8s
      await new Promise(r => setTimeout(r, retryAfterMs));
      return hsRequest(opts, attempt + 1);
    }
    throw err;   // re-throw if not 429 or out of retries
  }
};

// ── HubSpot Deal Upsert via REST API ─────────────────────────────────────
// Uses hsRequest (429-aware) for all HubSpot calls.
// Logic:
//   1. Search deals by azox_lead_id custom property
//   2. If found → PATCH to update stage
//   3. If not found → POST to create + associate with contact

const ctx   = $input.first().json;
const token = $env.HUBSPOT_API_KEY;

const headers = {
  'Authorization': `Bearer ${token}`,
  'Content-Type':  'application/json'
};

const contactId = ctx.vid || ctx.id ||
  $items('HubSpot — Upsert Contact')[0].json.vid ||
  $items('HubSpot — Upsert Contact')[0].json.id;

// ── Step 1: Search for existing deal ─────────────────────────────────────
const searchResp = await hsRequest({
  method:  'POST',
  url:     'https://api.hubapi.com/crm/v3/objects/deals/search',
  headers,
  body: JSON.stringify({
    filterGroups: [{
      filters: [{
        propertyName: 'azox_lead_id',
        operator:     'EQ',
        value:        ctx.lead_id
      }]
    }],
    properties: ['dealname', 'dealstage', 'pipeline', 'azox_lead_id'],
    limit: 1
  })
});

const searchResult   = typeof searchResp === 'string' ? JSON.parse(searchResp) : searchResp;
const existingDeal   = searchResult.results?.[0];
const existingDealId = existingDeal?.id || ctx.hubspot_deal_id || null;

let dealId;
let dealAction;

if (existingDealId) {
  // ── Update existing deal ──────────────────────────────────────────────
  const updateResp = await hsRequest({
    method:  'PATCH',
    url:     `https://api.hubapi.com/crm/v3/objects/deals/${existingDealId}`,
    headers,
    body: JSON.stringify({
      properties: {
        dealstage:        ctx.deal_stage,
        azox_status:      ctx.status,
        azox_last_action: ctx.event
      }
    })
  });
  const updated = typeof updateResp === 'string' ? JSON.parse(updateResp) : updateResp;
  dealId     = updated.id || existingDealId;
  dealAction = 'updated';

} else {
  // ── Create new deal ───────────────────────────────────────────────────
  const createResp = await hsRequest({
    method:  'POST',
    url:     'https://api.hubapi.com/crm/v3/objects/deals',
    headers,
    body: JSON.stringify({
      properties: {
        dealname:         ctx.hubspot_deal_props.dealname,
        amount:           ctx.hubspot_deal_props.amount,
        dealstage:        ctx.deal_stage,
        pipeline:         ctx.pipeline_id,
        closedate:        ctx.hubspot_deal_props.closedate,
        azox_lead_id:     ctx.lead_id,
        azox_status:      ctx.status,
        azox_tier:        ctx.tier,
        azox_last_action: ctx.event
      },
      associations: contactId ? [{
        to:    { id: String(contactId) },
        types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 3 }]
      }] : []
    })
  });
  const created = typeof createResp === 'string' ? JSON.parse(createResp) : createResp;
  dealId     = created.id;
  dealAction = 'created';

  // Associate deal ↔ contact (non-fatal if already exists)
  if (contactId && dealId) {
    await hsRequest({
      method:  'PUT',
      url:     `https://api.hubapi.com/crm/v3/objects/deals/${dealId}/associations/contacts/${contactId}/deal_to_contact`,
      headers,
      body:    JSON.stringify({})
    }).catch(() => {});
  }
}

return [{
  json: {
    ...ctx,
    hubspot_contact_id_resolved: String(contactId || ''),
    hubspot_deal_id_resolved:    String(dealId    || ''),
    hubspot_deal_action:         dealAction
  }
}];

// ── HubSpot 429-aware HTTP wrapper ───────────────────────────────────────
// Retries on 429 Too Many Requests (HubSpot: 100 req / 10 sec).
// Respects Retry-After header if present; falls back to 2s → 4s → 8s.
// Max 3 retries. Throws on 4th failure or non-429 error.
const hsRequest = async (opts, attempt = 0) => {
  try {
    return await $helpers.httpRequest(opts);
  } catch (err) {
    const status = err.response?.statusCode || err.statusCode || 0;
    if (status === 429 && attempt < 3) {
      const retryAfterMs =
        parseInt(err.response?.headers?.['retry-after'] || '0', 10) * 1000
        || (2 ** attempt) * 2000;   // 2s, 4s, 8s
      await new Promise(r => setTimeout(r, retryAfterMs));
      return hsRequest(opts, attempt + 1);
    }
    throw err;   // re-throw if not 429 or out of retries
  }
};

// ── Log engagement (email/note/meeting) to HubSpot ───────────────────────
// Uses hsRequest (429-aware) for the engagements API call.

const ctx       = $input.first().json;
const token     = $env.HUBSPOT_API_KEY;
const contactId = ctx.hubspot_contact_id_resolved;
const dealId    = ctx.hubspot_deal_id_resolved;

if (!contactId) {
  return [{ json: { ...ctx, hubspot_engagement_id: null, engagement_skipped: true } }];
}

const headers = {
  'Authorization': `Bearer ${token}`,
  'Content-Type':  'application/json'
};

const EVENT_MAP = {
  'email.sent':     { type: 'EMAIL',   subject: ctx.subject || 'Outreach email sent',   body: `Step ${ctx.step_number || ''} — ${ctx.strategy_used || 'outreach'} strategy` },
  'reply.received': { type: 'NOTE',    subject: 'Lead replied',                          body: `Intent: ${ctx.intent || 'unknown'} | Sentiment: ${ctx.sentiment || 'unknown'} | Summary: ${ctx.reply_summary || ''}` },
  'meeting.booked': { type: 'MEETING', subject: 'Meeting booked via AZOX',              body: `Scheduled: ${ctx.scheduled_at || 'TBC'} | Meeting ID: ${ctx.meeting_id || ''}` },
  'lead.scored':    { type: 'NOTE',    subject: 'ICP score assigned by AZOX',           body: `Tier: ${ctx.tier} | Score: ${ctx.score} | Breakdown: ${JSON.stringify(ctx.score_breakdown || {}).slice(0, 200)}` }
};

const engMap = EVENT_MAP[ctx.event] || {
  type: 'NOTE', subject: ctx.event,
  body: JSON.stringify({ event: ctx.event }).slice(0, 500)
};

const engBody = {
  engagement: { active: true, type: engMap.type, timestamp: Date.now() },
  associations: {
    contactIds: [parseInt(contactId)],
    dealIds:    dealId ? [parseInt(dealId)] : []
  },
  metadata: {
    subject: engMap.subject,
    body:    engMap.body,
    ...(engMap.type === 'EMAIL' ? {
      from:   { email: $env.SENDER_EMAIL },
      to:     [{ email: ctx.email }],
      status: 'SENT'
    } : {}),
    ...(engMap.type === 'MEETING' ? {
      startTime:      ctx.scheduled_at ? new Date(ctx.scheduled_at).getTime() : Date.now(),
      endTime:        ctx.scheduled_at ? new Date(ctx.scheduled_at).getTime() + 1800000 : Date.now() + 1800000,
      title:          engMap.subject,
      meetingOutcome: 'SCHEDULED'
    } : {})
  }
};

const resp   = await hsRequest({
  method: 'POST',
  url:    'https://api.hubapi.com/engagements/v1/engagements',
  headers,
  body:   JSON.stringify(engBody)
});
const result = typeof resp === 'string' ? JSON.parse(resp) : resp;

return [{ json: { ...ctx, hubspot_engagement_id: result?.engagement?.id || null } }];

// ── Salesforce OAuth2 client_credentials flow ────────────────────────────
// Uses Connected App client_id + client_secret for server-to-server auth.
// Token is cached in Redis for 1h to avoid repeated auth calls.

const cacheKey = 'salesforce:access_token';

// Check Redis cache first
let cached = null;
try {
  const r = await $helpers.redis.get(cacheKey);
  if (r) cached = JSON.parse(r);
} catch(_) {}

if (cached?.access_token) {
  return [{ json: { ...$input.first().json, sf_access_token: cached.access_token, sf_instance_url: cached.instance_url } }];
}

// Fetch new token
const params = new URLSearchParams({
  grant_type:    'client_credentials',
  client_id:     $env.SALESFORCE_CLIENT_ID,
  client_secret: $env.SALESFORCE_CLIENT_SECRET
});

const resp = await $helpers.httpRequest({
  method:  'POST',
  url:     `https://${$env.SALESFORCE_DOMAIN || 'login.salesforce.com'}/services/oauth2/token`,
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body:    params.toString()
});

const token = typeof resp === 'string' ? JSON.parse(resp) : resp;

if (!token.access_token) throw new Error('SF_AUTH_FAILED: ' + JSON.stringify(token));

// Cache for 55 minutes (tokens expire after 60m)
await $helpers.redis.set(cacheKey, JSON.stringify({
  access_token: token.access_token,
  instance_url: token.instance_url
}), 'EX', 3300);

return [{
  json: {
    ...$input.first().json,
    sf_access_token:  token.access_token,
    sf_instance_url:  token.instance_url
  }
}];

// ── Salesforce Contact Upsert via Composite API ──────────────────────────
// Uses PATCH /sobjects/Contact/email/{email} (External ID upsert).
// Requires "Email" field marked as External ID in Salesforce.

const ctx     = $input.first().json;
const baseUrl = ctx.sf_instance_url;
const token   = ctx.sf_access_token;

const headers = {
  'Authorization': `Bearer ${token}`,
  'Content-Type':  'application/json'
};

const contactBody = {
  FirstName:   ctx.first_name || '',
  LastName:    ctx.last_name  || ctx.full_name || ctx.email,
  Title:       ctx.title      || '',
  AccountName: ctx.company    || '',
  Phone:       ctx.phone      || '',
  LeadSource:  'AZOX AI',
  // Custom fields — must exist in Salesforce org
  AZOX_Lead_ID__c:     ctx.lead_id,
  AZOX_Score__c:       ctx.score    || 0,
  AZOX_Tier__c:        ctx.tier     || '',
  AZOX_Status__c:      ctx.status   || '',
  AZOX_Last_Action__c: ctx.event    || ''
};

// Upsert by email (External ID)
const encodedEmail = encodeURIComponent(ctx.email);
const resp = await $helpers.httpRequest({
  method:  'PATCH',
  url:     `${baseUrl}/services/data/v59.0/sobjects/Contact/Email/${encodedEmail}`,
  headers,
  body:    JSON.stringify(contactBody)
});

// 204 = updated, 201 = created (no body on PATCH upsert)
// We need to query to get the ID
const queryResp = await $helpers.httpRequest({
  method:  'GET',
  url:     `${baseUrl}/services/data/v59.0/query?q=SELECT+Id+FROM+Contact+WHERE+Email='${encodedEmail}'+LIMIT+1`,
  headers
});

const queryResult = typeof queryResp === 'string' ? JSON.parse(queryResp) : queryResp;
const sfContactId = queryResult?.records?.[0]?.Id || ctx.salesforce_contact_id || null;

return [{ json: { ...ctx, sf_contact_id: sfContactId } }];

// ── Salesforce Opportunity Upsert ────────────────────────────────────────
// Maps AZOX status to Salesforce opportunity stages.
// Upsert by AZOX_Lead_ID__c (External ID on Opportunity object).

const ctx     = $input.first().json;
const baseUrl = ctx.sf_instance_url;
const token   = ctx.sf_access_token;

const headers = {
  'Authorization': `Bearer ${token}`,
  'Content-Type':  'application/json'
};

// AZOX status → Salesforce opportunity stage
const SF_STAGE_MAP = {
  new:              'Prospecting',
  scored:           'Qualification',
  in_sequence:      'Needs Analysis',
  replied:          'Value Proposition',
  meeting_proposed: 'Proposal/Price Quote',
  meeting_booked:   'Perception Analysis'
};

const sfStage = SF_STAGE_MAP[ctx.status] || 'Prospecting';

const oppBody = {
  Name:            `${ctx.company || ''} — ${ctx.full_name || ctx.email}`,
  StageName:       sfStage,
  CloseDate:       new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10),
  LeadSource:      'AZOX AI',
  Amount:          ctx.annual_revenue || 0,
  AccountId:       ctx.sf_account_id  || null,
  AZOX_Lead_ID__c: ctx.lead_id,
  AZOX_Tier__c:    ctx.tier   || '',
  AZOX_Score__c:   ctx.score  || 0
};

// Upsert by AZOX_Lead_ID__c
const resp = await $helpers.httpRequest({
  method:  'PATCH',
  url:     `${baseUrl}/services/data/v59.0/sobjects/Opportunity/AZOX_Lead_ID__c/${ctx.lead_id}`,
  headers,
  body:    JSON.stringify(oppBody)
}).catch(e => ({ error: e.message }));

// Get the Opportunity ID
let sfOppId = ctx.salesforce_opp_id || null;
try {
  const q = await $helpers.httpRequest({
    method: 'GET',
    url:    `${baseUrl}/services/data/v59.0/query?q=SELECT+Id+FROM+Opportunity+WHERE+AZOX_Lead_ID__c='${ctx.lead_id}'+LIMIT+1`,
    headers
  });
  const qr = typeof q === 'string' ? JSON.parse(q) : q;
  sfOppId = qr?.records?.[0]?.Id || sfOppId;
} catch(_) {}

return [{ json: { ...ctx, sf_opportunity_id: sfOppId } }];

