// ── Parse HubSpot deal.propertyChange webhook ─────────────────────────────
// HubSpot sends arrays of change events.
// We care about: dealstage changes on deals that have azox_lead_id set.

const body = $input.first().json.body || $input.first().json;
const events = Array.isArray(body) ? body : [body];

// Filter for deal stage changes
const dealChanges = events.filter(e =>
  e.subscriptionType === 'deal.propertyChange' &&
  e.propertyName     === 'dealstage'
);

if (dealChanges.length === 0) {
  return [{ json: { skip: true, reason: 'no_relevant_events', raw: events.length } }];
}

// Take the first (or most recent) relevant change
const change = dealChanges[0];

return [{
  json: {
    hs_deal_id:       String(change.objectId || ''),
    hs_property:      change.propertyName,
    hs_new_value:     change.propertyValue || '',
    hs_subscription:  change.subscriptionType,
    hs_portal_id:     change.portalId,
    received_at:      new Date().toISOString()
  }
}];

// ── Map HubSpot closed stage to lead_outcome record ──────────────────────
// Only write outcome when the deal reaches a terminal stage.

const dealData  = $input.first().json;
const props     = dealData.properties || {};
const azoxLeadId = props.azox_lead_id?.value || props.azox_lead_id || null;

if (!azoxLeadId) {
  return [{ json: { skip: true, reason: 'no_azox_lead_id_on_deal' } }];
}

// Terminal stage mapping
const TERMINAL_STAGES = {
  closedwon:          { held: true,  result: 'won' },
  closedlost:         { held: false, result: 'lost' },
  'Closed Won':       { held: true,  result: 'won' },
  'Closed Lost':      { held: false, result: 'lost' }
};

const stage    = props.dealstage?.value || props.dealstage || '';
const terminal = TERMINAL_STAGES[stage];

if (!terminal) {
  return [{ json: { skip: true, reason: `non_terminal_stage: ${stage}` } }];
}

const amount = parseInt(props.amount?.value || props.amount || 0, 10);

return [{
  json: {
    azox_lead_id:  azoxLeadId,
    deal_result:   terminal.result,
    meeting_held:  terminal.held,
    deal_value:    amount,
    hs_deal_id:    dealData.id || String(dealData.hs_deal_id || ''),
    hs_stage:      stage,
    ready_to_write: true
  }
}];

const err = $input.first().error || {};
const msg = err.message || 'Unknown error in WF-08';

return [{
  json: {
    status:       msg.includes('UNAUTHORIZED') ? 'unauthorized' :
                  msg.includes('LEAD_NOT_FOUND') ? 'lead_not_found' : 'error',
    message:      msg,
    workflow:     'WF-08',
    timestamp:    new Date().toISOString(),
    execution_id: $execution.id
  }
}];
